using Microsoft.EntityFrameworkCore; using Microsoft.IdentityModel.Tokens; using System.IdentityModel.Tokens.Jwt; using System.Security.Claims; using System.Text; using Mft.Application.Abstractions; using Mft.Application.Contracts; using Mft.Infrastructure.Persistence; namespace Mft.Infrastructure; public sealed class AuthService(AppDbContext db,IConfiguration config):IAuthService { public async Task<LoginResponse?> LoginAsync(LoginRequest r,CancellationToken ct){var u=await db.Users.AsNoTracking().SingleOrDefaultAsync(x=>x.Username==r.Username&&x.Role==r.Role&&x.IsActive,ct);if(u is null||!BCrypt.Net.BCrypt.Verify(r.Password,u.PasswordHash))return null;var key=new SymmetricSecurityKey(Encoding.UTF8.GetBytes(config["Jwt:Key"]!));var claims=new[]{new Claim(JwtRegisteredClaimNames.Sub,u.Id.ToString()),new Claim(ClaimTypes.Name,u.Username),new Claim(ClaimTypes.Role,u.Role.ToString())};var token=new JwtSecurityToken(claims:claims,expires:DateTime.UtcNow.AddHours(8),signingCredentials:new SigningCredentials(key,SecurityAlgorithms.HmacSha256));return new(new JwtSecurityTokenHandler().WriteToken(token),u.Id,u.FullName,u.Role);} }